const fs = require('fs');

function main() {
    const buffer = fs.readFileSync(0);
    let offset = 0;

    function nextInt() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return null;
        let res = 0;
        while (offset < buffer.length && buffer[offset] > 32) {
            res = res * 10 + (buffer[offset] - 48);
            offset++;
        }
        return res;
    }

    const n = nextInt();
    if (n === null) return;
    const m = nextInt();

    const bitA = new Float64Array(n + 2);
    const bitB = new Float64Array(n + 2);

    function addBIT(bit, idx, val) {
        for (; idx <= n + 1; idx += idx & -idx) {
            bit[idx] += val;
        }
    }

    function queryBIT(bit, idx) {
        let sum = 0;
        for (; idx > 0; idx -= idx & -idx) {
            sum += bit[idx];
        }
        return sum;
    }

    function addRange(l, r, a, b) {
        addBIT(bitA, l, a);
        addBIT(bitA, r + 1, -a);
        addBIT(bitB, l, b);
        addBIT(bitB, r + 1, -b);
    }

    const out = [];

    for (let k = 0; k < m; k++) {
        const type = nextInt();
        if (type === 1) {
            const i = nextInt();
            const v = nextInt();
            const l = i;
            const r = Math.min(n, i + v - 1);
            if (l <= r) {
                addRange(l, r, -1, v + i);
            }
        } else if (type === 2) {
            const i = nextInt();
            const v = nextInt();
            const l = Math.max(1, i - v + 1);
            const r = i;
            if (l <= r) {
                addRange(l, r, 1, v - i);
            }
        } else if (type === 3) {
            const i = nextInt();
            const a = queryBIT(bitA, i);
            const b = queryBIT(bitB, i);
            const ans = a * i + b;
            out.push(ans);
            if (out.length >= 10000) {
                process.stdout.write(out.join('\n') + '\n');
                out.length = 0;
            }
        }
    }

    if (out.length > 0) {
        process.stdout.write(out.join('\n') + '\n');
    }
}

main();
